/* ==========================================================================
   DocEase Clinic - Clinic Locations Page
   Matches DocEase Sage Green, Navy Blue & White Theme + Prototype Layout
   ========================================================================== */

:root {
  /* Navy Blue & Sage Green Palette (shared with DocEase Services & Homepage) */
  --color-navy: #162d50;
  --color-navy-dark: #0f203b;
  --color-navy-soft: #e8eef6;

  --color-sage: #5f8567;
  --color-sage-dark: #486950;
  --color-sage-light: #e7f0e9;
  --color-sage-tint: #f4f8f5;

  --color-bg: var(--color-sage-tint);
  --color-surface: #ffffff;
  --color-text: #152238;
  --color-text-muted: #526277;
  --color-border: #cedbd1;

  --font-sans: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto,
    "Helvetica Neue", Arial, sans-serif;

  --container-max: 1160px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 999px;

  --shadow-sm: 0 2px 8px rgba(22, 45, 80, 0.06);
  --shadow-md: 0 8px 24px rgba(22, 45, 80, 0.09);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

main {
  flex: 1;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--color-navy);
  text-decoration: none;
}

a:hover {
  color: var(--color-sage-dark);
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--color-sage);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -3rem;
  background: var(--color-navy);
  color: #ffffff;
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  z-index: 1000;
  font-weight: 600;
}

.skip-link:focus {
  top: 0.75rem;
  color: #ffffff;
}

.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* ==========================================================================
   Shared Header / Navbar
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: var(--color-surface);
  border-bottom: 2px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.nav-wrapper {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  min-height: 76px;
  gap: 1.25rem;
}

.nav-wrapper > * {
  min-width: 0;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--color-navy);
}

.brand__logo {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  border: 1px solid var(--color-border);
  flex-shrink: 0;
}

.brand__sub {
  display: block;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--color-sage-dark);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.nav-center {
  display: flex;
  justify-content: center;
}

.nav-menu {
  display: flex;
  align-items: center;
  gap: 1.35rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-link {
  display: inline-block;
  padding: 0.45rem 0.25rem;
  font-weight: 600;
  font-size: 0.96rem;
  color: var(--color-text);
  border-bottom: 2px solid transparent;
  transition: color 0.18s ease, border-color 0.18s ease;
  white-space: nowrap;
}

.nav-link:hover {
  color: var(--color-navy);
  border-bottom-color: var(--color-sage);
}

.nav-link.is-active {
  color: var(--color-navy);
  border-bottom-color: var(--color-navy);
}

.nav-phone {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.52rem 1rem;
  border-radius: var(--radius-pill);
  background: var(--color-navy);
  color: #ffffff;
  font-weight: 600;
  font-size: 0.9rem;
  white-space: nowrap;
  transition: background-color 0.18s ease;
}

.nav-phone:hover {
  background: var(--color-sage-dark);
  color: #ffffff;
}

.nav-toggle {
  display: none;
  background: var(--color-sage-light);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.45rem 0.7rem;
  cursor: pointer;
  color: var(--color-navy);
  font-weight: 600;
}

/* ==========================================================================
   Clinic Locations Section (Left: Heading & 3 Cards | Right: Search & Map)
   ========================================================================== */
.locations-section {
  padding: 2.65rem 0 3.25rem;
  background: linear-gradient(
    135deg,
    var(--color-sage-light) 0%,
    var(--color-bg) 55%,
    var(--color-navy-soft) 100%
  );
}

.locations-layout {
  display: grid;
  grid-template-columns: minmax(320px, 0.95fr) 1.25fr;
  gap: 2.25rem;
  align-items: start;
}

.locations-layout > * {
  min-width: 0;
}

.locations-header {
  margin-bottom: 1.2rem;
}

.locations-heading {
  margin: 0;
  font-size: clamp(1.55rem, 2.7vw, 2.05rem);
  line-height: 1.2;
  color: var(--color-navy);
  letter-spacing: -0.015em;
}

.search-status {
  margin: 0.45rem 0 0;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-sage-dark);
}

/* Stacked Clinic Cards on the Left */
.clinic-cards {
  display: grid;
  gap: 1.15rem;
}

.clinic-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-left: 5px solid var(--color-navy);
  border-radius: var(--radius-lg);
  padding: 1.2rem 1.35rem 1.1rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  transition: transform 0.18s ease, box-shadow 0.18s ease,
    border-color 0.18s ease;
}

.clinic-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-sage);
  border-left-color: var(--color-sage-dark);
}

.clinic-card[hidden] {
  display: none;
}

.clinic-card__body {
  display: grid;
  gap: 0.42rem;
}

.clinic-card__name {
  margin: 0 0 0.15rem;
  font-size: 1.18rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-navy);
}

.clinic-card__info {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.96rem;
  color: var(--color-text-muted);
}

.clinic-card__icon {
  color: var(--color-sage-dark);
  flex-shrink: 0;
}

.clinic-card__phone {
  color: var(--color-text);
  font-weight: 600;
}

.clinic-card__phone:hover {
  color: var(--color-navy);
  text-decoration: underline;
}

.clinic-card__footer {
  display: flex;
  justify-content: flex-end;
  padding-top: 0.2rem;
}

.book-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.56rem 1.25rem;
  border-radius: var(--radius-pill);
  background: var(--color-navy);
  border: 2px solid var(--color-navy);
  color: #ffffff;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: background-color 0.18s ease, border-color 0.18s ease,
    transform 0.16s ease;
}

.book-btn:hover {
  background: var(--color-sage-dark);
  border-color: var(--color-sage-dark);
  color: #ffffff;
  transform: translateY(-1px);
}

/* Empty State (Shown when search finds no clinics) */
.empty-state {
  background: var(--color-surface);
  border: 2px dashed var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem 1.5rem;
  text-align: center;
  box-shadow: var(--shadow-sm);
}

.empty-state__title {
  margin: 0 0 0.45rem;
  font-size: 1.15rem;
  color: var(--color-navy);
}

.empty-state__desc {
  margin: 0 0 1.15rem;
  font-size: 0.94rem;
  color: var(--color-text-muted);
}

.empty-state__btn {
  padding: 0.55rem 1.2rem;
  border-radius: var(--radius-pill);
  background: var(--color-sage-light);
  border: 1.5px solid var(--color-sage);
  color: var(--color-navy);
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.16s ease, color 0.16s ease;
}

.empty-state__btn:hover {
  background: var(--color-sage-dark);
  border-color: var(--color-sage-dark);
  color: #ffffff;
}

/* Right Column: Search Bar Directly Above Large Map */
.locations-map-col {
  display: grid;
  gap: 1rem;
  align-content: start;
}

.clinic-search {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-pill);
  padding: 0.35rem 0.4rem 0.35rem 1rem;
  box-shadow: var(--shadow-sm);
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.clinic-search:focus-within {
  border-color: var(--color-navy);
  box-shadow: var(--shadow-md);
}

.clinic-search__icon {
  color: var(--color-sage-dark);
  flex-shrink: 0;
}

.clinic-search__input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: transparent;
  padding: 0.45rem 0.25rem;
  font-size: 0.96rem;
  color: var(--color-text);
  outline: none;
}

.clinic-search__input::placeholder {
  color: var(--color-text-muted);
}

.clinic-search__clear {
  background: var(--color-sage-light);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  padding: 0.35rem 0.75rem;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--color-navy);
  cursor: pointer;
  transition: background-color 0.16s ease;
}

.clinic-search__clear:hover {
  background: var(--color-border);
}

.clinic-search__btn {
  padding: 0.55rem 1.2rem;
  border-radius: var(--radius-pill);
  border: 0;
  background: var(--color-navy);
  color: #ffffff;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color 0.18s ease;
}

.clinic-search__btn:hover {
  background: var(--color-sage-dark);
}

.map-card {
  margin: 0;
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 0.85rem;
  box-shadow: var(--shadow-md);
}

.map-card__img {
  width: 100%;
  height: auto;
  max-height: 540px;
  object-fit: contain;
  border-radius: var(--radius-md);
  background: #ffffff;
}

/* ==========================================================================
   Appointment Booking Modal
   ========================================================================== */
.modal-backdrop[hidden] {
  display: none;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1100;
  background: rgba(15, 32, 59, 0.58);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.modal-dialog {
  width: 100%;
  max-width: 520px;
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-md);
}

.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.modal-eyebrow {
  margin: 0 0 0.2rem;
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-sage-dark);
}

.modal-title {
  margin: 0;
  font-size: 1.35rem;
  color: var(--color-navy);
}

.modal-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  background: var(--color-sage-tint);
  color: var(--color-navy);
  font-size: 1.35rem;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.modal-close:hover {
  background: var(--color-sage-light);
}

.modal-clinic-summary {
  background: var(--color-sage-tint);
  border: 1px solid var(--color-border);
  border-left: 4px solid var(--color-sage-dark);
  border-radius: var(--radius-sm);
  padding: 0.75rem 0.95rem;
  margin-bottom: 1.15rem;
  display: grid;
  gap: 0.15rem;
  font-size: 0.9rem;
  color: var(--color-text-muted);
}

.modal-clinic-summary strong {
  color: var(--color-navy);
  font-size: 1rem;
}

.modal-form {
  display: grid;
  gap: 0.95rem;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.85rem;
}

.form-field {
  display: grid;
  gap: 0.32rem;
}

.form-field label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-navy);
}

.form-field input,
.form-field select {
  width: 100%;
  padding: 0.55rem 0.75rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  font-size: 0.94rem;
}

.form-field input:focus,
.form-field select:focus {
  outline: none;
  border-color: var(--color-navy);
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 0.4rem;
}

.modal-link-btn {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--color-navy);
  text-decoration: underline;
}

.modal-link-btn:hover {
  color: var(--color-sage-dark);
}

.modal-confirmation {
  text-align: center;
  padding: 0.5rem 0;
}

.confirmation-badge {
  width: 48px;
  height: 48px;
  margin: 0 auto 0.75rem;
  border-radius: 50%;
  background: var(--color-sage-light);
  border: 2px solid var(--color-sage-dark);
  color: var(--color-sage-dark);
  font-size: 1.4rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-confirmation h3 {
  margin: 0 0 0.45rem;
  color: var(--color-navy);
}

.modal-confirmation p {
  margin: 0 0 1.2rem;
  font-size: 0.94rem;
  color: var(--color-text-muted);
}

/* ==========================================================================
   Shared Navy-Blue Footer
   ========================================================================== */
.site-footer {
  background: var(--color-navy-dark);
  color: #dbe4ef;
  padding: 2.5rem 0 1.25rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 2rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  color: #ffffff;
  font-weight: 700;
  font-size: 1.15rem;
  margin-bottom: 0.65rem;
}

.footer-brand__logo {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  border: 1px solid rgba(255, 255, 255, 0.2);
  flex-shrink: 0;
}

.footer-tagline {
  margin: 0;
  font-size: 0.9rem;
  max-width: 300px;
}

.footer-heading {
  margin: 0 0 0.75rem;
  color: #9ec5a6;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
  font-size: 0.92rem;
}

.footer-lines a {
  color: #c5d7cb;
}

.footer-lines a:hover {
  color: #ffffff;
  text-decoration: underline;
}

.footer-bottom {
  padding-top: 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.84rem;
  color: #a9b9cd;
}

/* ==========================================================================
   Responsive Breakpoints
   ========================================================================== */
@media (max-width: 960px) {
  .locations-layout {
    grid-template-columns: 1fr;
    gap: 1.85rem;
  }

  .map-card__img {
    max-height: 460px;
  }
}

@media (max-width: 760px) {
  .nav-wrapper {
    grid-template-columns: 1fr auto;
  }

  .nav-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
  }

  .nav-phone {
    display: none;
  }

  .nav-center {
    grid-column: 1 / -1;
    justify-content: stretch;
  }

  .nav-menu {
    display: none;
    width: 100%;
    flex-direction: column;
    align-items: stretch;
    gap: 0.25rem;
    padding: 0.5rem 0 0.85rem;
    border-top: 1px solid var(--color-border);
  }

  .nav-menu.is-open {
    display: flex;
  }

  .locations-section {
    padding: 2rem 0 2.5rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 540px) {
  .clinic-card {
    padding: 1rem 1.05rem;
  }

  .clinic-card__footer {
    justify-content: stretch;
  }

  .clinic-card__footer .book-btn {
    width: 100%;
  }

  .clinic-search {
    padding: 0.3rem 0.35rem 0.3rem 0.8rem;
  }

  .clinic-search__btn {
    padding: 0.5rem 0.9rem;
  }

  .form-row {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================================
   DocEase Clinic - Clinic Locations Page Script
   ========================================================================== */

(function () {
  "use strict";

  function initNavigation() {
    const toggle = document.getElementById("navToggle");
    const menu = document.getElementById("navMenu");
    if (!toggle || !menu) return;

    function closeMenu() {
      menu.classList.remove("is-open");
      toggle.setAttribute("aria-expanded", "false");
    }

    toggle.addEventListener("click", () => {
      const isOpen = menu.classList.toggle("is-open");
      toggle.setAttribute("aria-expanded", String(isOpen));
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && menu.classList.contains("is-open")) {
        closeMenu();
        toggle.focus();
      }
    });
  }

  function normalizeText(value) {
    return String(value || "").toLowerCase().trim();
  }

  function normalizeDigits(value) {
    return String(value || "").replace(/\D/g, "");
  }

  function initClinicSearch() {
    const form = document.getElementById("clinicSearchForm");
    const input = document.getElementById("clinicSearchInput");
    const clearBtn = document.getElementById("clearSearchBtn");
    const resetBtn = document.getElementById("resetSearchBtn");
    const cardsContainer = document.getElementById("clinicCards");
    const emptyState = document.getElementById("noClinicsMessage");
    const emptyDetail = document.getElementById("noClinicsDetail");
    const statusEl = document.getElementById("searchStatus");

    if (!form || !input || !cardsContainer || !emptyState) return;

    const cards = Array.from(cardsContainer.querySelectorAll(".clinic-card"));

    function filterClinics() {
      const rawQuery = input.value.trim();
      const textQuery = normalizeText(rawQuery);
      const digitQuery = normalizeDigits(rawQuery);

      if (clearBtn) {
        clearBtn.hidden = rawQuery.length === 0;
      }

      let visibleCount = 0;

      cards.forEach((card) => {
        const name = normalizeText(card.dataset.clinicName);
        const address = normalizeText(card.dataset.clinicAddress);
        const phone = normalizeText(card.dataset.clinicPhone);
        const phoneDigits = normalizeDigits(card.dataset.clinicPhone);

        const matchesText =
          !textQuery ||
          name.includes(textQuery) ||
          address.includes(textQuery) ||
          phone.includes(textQuery);

        const matchesDigits =
          digitQuery.length >= 2 && phoneDigits.includes(digitQuery);

        const isMatch = matchesText || matchesDigits;
        card.hidden = !isMatch;
        if (isMatch) visibleCount += 1;
      });

      if (visibleCount === 0) {
        emptyState.hidden = false;
        if (emptyDetail) {
          emptyDetail.textContent = `No DocEase clinic matched "${rawQuery}". Try searching by clinic name (South Jay, Town Center, Hylo East), street address, or phone number.`;
        }
      } else {
        emptyState.hidden = true;
      }

      if (statusEl) {
        if (!rawQuery) {
          statusEl.hidden = true;
          statusEl.textContent = "";
        } else {
          statusEl.hidden = false;
          statusEl.textContent =
            visibleCount === 0
              ? `0 clinics found for "${rawQuery}"`
              : `Showing ${visibleCount} of ${cards.length} clinics for "${rawQuery}"`;
        }
      }
    }

    function resetSearch() {
      input.value = "";
      filterClinics();
      input.focus();
    }

    input.addEventListener("input", filterClinics);

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      filterClinics();
    });

    if (clearBtn) {
      clearBtn.addEventListener("click", resetSearch);
    }

    if (resetBtn) {
      resetBtn.addEventListener("click", resetSearch);
    }
  }

  function initAppointmentModal() {
    const modal = document.getElementById("bookingModal");
    const closeBtn = document.getElementById("closeModalBtn");
    const doneBtn = document.getElementById("doneBookingBtn");
    const form = document.getElementById("bookingForm");
    const confirmation = document.getElementById("bookingConfirmation");
    const confirmationMessage = document.getElementById("confirmationMessage");
    const modalClinicName = document.getElementById("modalClinicName");
    const modalClinicDetails = document.getElementById("modalClinicDetails");
    const bookingDateInput = document.getElementById("bookingDate");
    const bookingSpecialtySelect = document.getElementById("bookingSpecialty");
    const bookingTimeSelect = document.getElementById("bookingTime");
    const patientNameInput = document.getElementById("patientName");
    const findDoctorLink = document.getElementById("findDoctorLink");
    const bookButtons = document.querySelectorAll(".book-btn[data-clinic]");

    if (!modal || !form || !confirmation || bookButtons.length === 0) return;

    let lastFocusedButton = null;
    let activeClinicName = "";

    if (bookingDateInput) {
      const todayIso = new Date().toISOString().split("T")[0];
      bookingDateInput.min = todayIso;
      bookingDateInput.value = todayIso;
    }

    function openModal(triggerBtn) {
      lastFocusedButton = triggerBtn;
      activeClinicName = triggerBtn.dataset.clinic || "DocEase Clinic";
      const address = triggerBtn.dataset.address || "";
      const phone = triggerBtn.dataset.phone || "";

      if (modalClinicName) {
        modalClinicName.textContent = activeClinicName;
      }
      if (modalClinicDetails) {
        modalClinicDetails.textContent = `${address} | ${phone}`;
      }
      if (findDoctorLink) {
        findDoctorLink.href = `finddoctor.html?clinic=${encodeURIComponent(activeClinicName)}`;
      }

      form.hidden = false;
      confirmation.hidden = true;
      modal.hidden = false;
      document.body.style.overflow = "hidden";

      if (bookingSpecialtySelect) {
        bookingSpecialtySelect.focus();
      }
    }

    function closeModal() {
      modal.hidden = true;
      document.body.style.overflow = "";
      if (lastFocusedButton) {
        lastFocusedButton.focus();
      }
    }

    bookButtons.forEach((btn) => {
      btn.addEventListener("click", () => openModal(btn));
    });

    if (closeBtn) {
      closeBtn.addEventListener("click", closeModal);
    }

    if (doneBtn) {
      doneBtn.addEventListener("click", closeModal);
    }

    modal.addEventListener("click", (event) => {
      if (event.target === modal) {
        closeModal();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && !modal.hidden) {
        closeModal();
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const patientName = patientNameInput ? patientNameInput.value.trim() : "Patient";
      const specialty = bookingSpecialtySelect ? bookingSpecialtySelect.value : "General Medicine";
      const dateVal = bookingDateInput ? bookingDateInput.value : "";
      const timeVal = bookingTimeSelect ? bookingTimeSelect.value : "";

      if (confirmationMessage) {
        confirmationMessage.textContent = `Thank you, ${patientName}. Your ${specialty} appointment request at ${activeClinicName} for ${dateVal} at ${timeVal} has been submitted.`;
      }

      form.hidden = true;
      confirmation.hidden = false;
      form.reset();

      if (bookingDateInput) {
        const todayIso = new Date().toISOString().split("T")[0];
        bookingDateInput.value = todayIso;
      }
    });
  }

  document.addEventListener("DOMContentLoaded", () => {
    const yearEl = document.getElementById("currentYear");
    if (yearEl) {
      yearEl.textContent = String(new Date().getFullYear());
    }

    initNavigation();
    initClinicSearch();
    initAppointmentModal();
  });
})();

